9	4	To see all your enrolled courses, open the profile dropdown and select My Enrolled Courses. This page lists every course you are enrolled in, together with its current status. On the Courses page, you can also open the Filter by Course Category dropdown and select My Enrolled Courses. This only filters the tab you are currently viewing, so it shows your enrolled courses within that tab rather than all of them.	[-0.026775995,0.026402272,0.018688582,-0.10143852,0.04174673,-0.01578129,-0.03261327,-0.009501343,-0.025259536,0.0062347814,-0.017749397,-0.0066812863,0.012857775,0.016067892,0.24979031,-0.032875028,0.007953213,-0.0212422,0.0020600834,0.010143784,-0.008237617,0.0009179528,-0.022797907,-0.032161716,0.026662804,-0.004847515,0.042287752,0.05543924,0.048835743,-0.0054062153,-0.034271523,0.045908846,-0.007640515,-0.027593458,-0.015740512,0.028553816,0.00026864765,0.027679475,-0.031115282,0.01727762,0.015295315,0.03960493,0.001489784,-0.03469283,0.020063411,-0.020426374,-0.024042448,-0.029235667,-0.021616582,-0.0067473417,-0.012202717,0.008536606,-0.057161584,-0.42944357,0.02896977,-0.035025652,-0.016350873,0.029197222,-0.0060647195,0.0132361725,-0.016033268,0.015544433,-0.04976946,0.009167901,0.032171033,0.002522397,0.02895968,0.04342699,-0.032890525,0.020335488,0.024871826,0.046632145,-0.028953692,-0.007817613,0.018163538,-0.016757041,0.005863133,0.015562038,0.035834286,0.025201755,-0.00033066596,0.013191186,0.018357323,0.0018278664,0.03502503,0.0015335431,-0.007081192,0.004461623,-0.025612125,0.0062555564,-0.02814119,0.014022719,-0.015678966,0.01773996,0.01280745,-0.02839469,0.011810627,0.0026961796,-0.023876905,-0.020660274,-0.0058546104,-0.011740941,-0.011536455,-0.0032533112,0.02479741,-0.02072947,0.012522806,-0.019936671,-0.009135174,-0.0034324462,0.007364301,-0.0060398304,-0.007950302,-0.006695555,0.04153042,-0.37638837,-0.0037814672,0.0032214199,-0.011613961,-0.041050304,-0.036286652,-0.019979484,0.002227511,-0.047956668,-0.008486717,-0.003597326,0.0498